import React, { useState } from "react";
import axios from "axios";
import AlertBox from "./AlertBox";

function MaterialsStudent() {
  const [materials, setMaterials] = useState([]);
  const [courseId, setCourseId] = useState("");
  const [alert, setAlert] = useState(null);

  const loadMaterials = async () => {
    if (!courseId) {
      setAlert({
        message: "Please enter course ID",
        type: "error"
      });
      return;
    }

    try {
      const res = await axios.get(`http://localhost:8000/materials/${courseId}`);
      setMaterials(res.data.materials || []);
    } catch (err) {
      console.log(err.response?.data);
      setAlert({
        message: "Failed to load materials",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2>Study Materials</h2>

      <div style={{ display: "flex", gap: "10px", marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Enter Course ID"
          value={courseId}
          onChange={(e) => setCourseId(e.target.value)}
          style={{
            padding: "10px",
            borderRadius: "8px",
            border: "1px solid #ccc",
            width: "250px"
          }}
        />

        <button
          onClick={loadMaterials}
          style={{
            background: "#7b1fa2",
            color: "#fff",
            border: "none",
            padding: "10px 16px",
            borderRadius: "8px",
            cursor: "pointer"
          }}
        >
          Load Materials
        </button>
      </div>

      {materials.length === 0 ? (
        <p>No materials found.</p>
      ) : (
        materials.map((m) => (
          <div
            key={m.id}
            style={{
              border: "1px solid #ddd",
              borderRadius: "12px",
              padding: "15px",
              marginBottom: "15px",
              background: "#fff"
            }}
          >
            <h3>{m.title}</h3>

            <div style={{ display: "flex", gap: "15px" }}>
              <a
                href={`http://localhost:8000${m.file_url}`}
                target="_blank"
                rel="noreferrer"
                style={{ color: "#1976d2", fontWeight: "bold" }}
              >
                View PDF
              </a>

              <a
                href={`http://localhost:8000${m.file_url}`}
                download
                style={{ color: "#2e7d32", fontWeight: "bold" }}
              >
                Download PDF
              </a>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

export default MaterialsStudent;
